INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (1563, '[Infographic] Diễn biến cuộc chiến thương mại Mỹ Trung 2018', 'infographic-dien-bien-cuoc-chien-thuong-mai-my-trung-2018', '<p><strong>Cuộc chiến thương mại Mỹ Trung</strong> đang là đề tài kinh tế nóng hỏi của toàn cầu trong thời gian hiện nay. Chúng ta hãy nhìn lại một cách tổng quát cuộc chiến thương mại này nhé! Tổng thống Mỹ &#8211; Donal Trump với kinh nghiệm là một doanh nhân thành công có cơ sở nhất định để tin vào thắng lợi của nước Mỹ. Nhưng Trung Quốc với một tự hào về lịch sử, dân số và có một nền kinh tế nhảy vọt nhanh chóng cũng không phải là thế yếu hoàn toàn. Những diễn biến mới, lịch sử, nguồn gốc các cuộc chiến thương mại và sự phân tích của các chuyên gia trong cuộc chiến thương mại này sẽ được khái quát dễ hiểu qua sơ đồ Infographic.</p>
<h2>Infographic diễn biến cuộc chiến thương mại Mỹ Trung 2018</h2>
<p><figure id="attachment_1565" aria-describedby="caption-attachment-1565" style="width: 1280px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1565 size-full" src="https://media.huynhhieutravel.com/Infographic-Cuộc-chiến-thương-mại-Mỹ-Trung.jpg" alt="Infographic Cuộc chiến thương mại Mỹ Trung" width="1280" height="13128" srcset="https://media.huynhhieutravel.com/Infographic-Cuộc-chiến-thương-mại-Mỹ-Trung.jpg 1280w, https://media.huynhhieutravel.com/Infographic-Cuộc-chiến-thương-mại-Mỹ-Trung-768x7877.jpg 768w" sizes="(max-width: 1280px) 100vw, 1280px" /><figcaption id="caption-attachment-1565" class="wp-caption-text">Infographic Cuộc chiến thương mại Mỹ Trung</figcaption></figure></p>
', 'Cuộc chiến thương mại Mỹ Trung đang là đề tài kinh tế nóng hỏi của toàn cầu trong thời gian hiện nay. Chúng ta hãy nhìn lại một cách tổng quát cuộc chiến thương mại này nhé! Tổng thống Mỹ &#8211; Donal Trump với kinh nghiệm là một doanh nhân thành công có cơ sở [&hellip;]', 1566, 'post', '2018-08-18 06:19:04', '2023-04-23 12:35:02');
